      boolean canAccess(String page,String role){if("ADMIN".equalsIgnoreCase(role))return true;if("TELLER".equalsIgnoreCase(role))return !Set.of("User Management","Audit Logs").contains(page);return Set.of("Dashboard","Accounts","Transactions","Reports","Settings","Help & About").contains(page);}
      JButton navButton(String n){JButton b=new JButton("   ◦   "+n);b.setMaximumSize(new Dimension(210,40));b.setHorizontalAlignment(SwingConstants.LEFT);b.setForeground(new Color(210,221,236));b.setBackground(NAVY);b.setFont(new Font("Segoe UI",0,13));b.setBorder(new EmptyBorder(10,10,10,8));b.setFocusPainted(false);b.setContentAreaFilled(false);b.addActionListener(e->{for(Component c:((JPanel)sidebar.getComponent(1)).getComponents())if(c instanceof JButton x){x.setOpaque(false);x.setBackground(NAVY);x.setForeground(new Color(210,221,236));}b.setOpaque(true);b.setBackground(new Color(32,57,89));b.setForeground(Color.WHITE);});return b;}
